context_info = ()
for d in context:
    prompt = "Here is a document:\nBEGIN_DOCUMENT\n" + d + "\nEND_DOCUMENT\n" + "From this document alone, extract any information that could help identify the cover designer asked about below. Only include an item if the document clearly supports it.\nProvide a list of zero or more findings. For each, include 'Finding:' then 'Quotes:' and keep each finding concise.\nLook for any of the following:\n- A World Health Organization global report (published between 2012 and 2019 inclusive). If present, give: the report title, year, foreword author, introduction author, and any 'Cover design by' or 'Cover designer' credit (name and any bio details).\n- Any person profile/bio that matches ALL of these: completed a program named 'Leadership Strategies in Book Publishing' sometime between 2010 and 2019; earned a Bachelor's degree in Graphic Design between 2001 and 2009; previously worked at Malaria Consortium and also at Ogilvy & Mather. If present, give the full name and the details.\n- Any mention of an introduction author whose first name begins with 'Z' tied to a WHO report, and any evidence that the same 'Z' person co-authored an opinion piece with a co-author whose first name begins with 'J' published between 2021 and 2023.\nIf nothing relevant is present, output nothing."
    result = llm_query(prompt)
    context_info = context_info + (result,)

compiled = "Here are extracted findings from the provided documents:\n" + "\n\n".join(context_info) + "\n\n" + "Task: Using only the above findings, identify the specific WHO global report (2012-2019) that has a foreword by an Eritrean individual who holds an MSc in Immunology of Infectious Diseases from a UK university (note: Dr Tedros Adhanom Ghebreyesus fits this), and an introduction authored by someone whose first name begins with 'Z' who also co-authored an opinion piece with a co-author whose first name begins with 'J' between 2021 and 2023 (e.g., Zoleka Mandela with Jean Todt is an example pattern to check if present). Once you have identified the correct report, extract the cover designer credit from the findings.\nReturn only the cover designer's first and last name, nothing else."
final_answer = llm_query(compiled)
return_result(final_answer)